25	    private static final RowMapper<ReviewPo> REVIEW_MAPPER = (rs, n) -> new ReviewPo(
26	            rs.getString("review_id"),
27	            rs.getString("route_id"),
28	            rs.getInt("route_version"),
29	            rs.getLong("airspace_version"),
30	            rs.getString("conclusion"),
31	            decodeZoneIds(rs.getString("hit_zone_ids")),
32	            decodePoints(rs.getString("points_snapshot")),
33	            rs.getString("request_id"),
34	            rs.getLong("created_at"));
