39	                "SELECT review_id, route_id, route_version, airspace_version, conclusion, "
40	                        + "hit_zone_ids, points_snapshot, request_id, created_at "
41	                        + "FROM review WHERE review_id = ?",
42	                REVIEW_MAPPER, reviewId).stream().findFirst().orElse(null);
43	    }
