        "SELECT COUNT(*) FROM zone_ring WHERE zone_id = 'fz'", Integer.class));
assertEquals("REVOKED", jdbc.queryForObject(
        "SELECT status FROM no_fly_zone WHERE zone_id = 'fz'", String.class));

